// @toreview
"use client"

/**
 * @fileoverview Sidebar context — React context, provider, cookie-based persistence, and trigger for the sidebar system.
 * Manages sidebar open/collapsed state across desktop and mobile with keyboard shortcut support.
 * @module packages/ui/components/ui/sidebar/context
 * @package ui
 *
 * @example
 * import { SidebarProvider, useSidebar, SidebarTrigger } from '@saasflare/ui';
 * <SidebarProvider>
 *   <SidebarTrigger />
 *   {children}
 * </SidebarProvider>
 */

// ============================================================================
// SIDEBAR CONTEXT
// Context, provider, and constants for the sidebar component system
// ============================================================================

import * as React from "react"
import { SidebarSimpleIcon } from "@saasflare/ui"
import { useIsMobile } from "@saasflare/ui"
import { cn } from "@saasflare/ui"
import {
  useSaasflareProps,
  type SaasflareComponentProps,
} from "@saasflare/ui"
import { Button } from "@saasflare/ui"
import {
  TooltipProvider,
} from "@saasflare/ui"

// ============================================================================
// CONSTANTS
// ============================================================================

export const SIDEBAR_COOKIE_NAME = "sidebar_state"
/** Lifetime (seconds, 7 days) of the sidebar-state cookie written by {@link SidebarProvider}'s `setOpen`. */
export const SIDEBAR_COOKIE_MAX_AGE = 60 * 60 * 24 * 7
/** Expanded sidebar width on desktop; exposed as `--sidebar-width` by {@link SidebarProvider}. */
export const SIDEBAR_WIDTH = "16rem"
/** Sidebar width inside the mobile Sheet; applied as `--sidebar-width` by the mobile branch of `Sidebar`. */
export const SIDEBAR_WIDTH_MOBILE = "18rem"
/** Collapsed (icon-only) sidebar width; exposed as `--sidebar-width-icon` by {@link SidebarProvider}. */
export const SIDEBAR_WIDTH_ICON = "3rem"
/** Key that toggles the sidebar together with Cmd/Ctrl; registered by {@link SidebarProvider}. */
export const SIDEBAR_KEYBOARD_SHORTCUT = "b"

// ============================================================================
// CONTEXT
// ============================================================================

export type SidebarContextProps = {
  state: "expanded" | "collapsed" | "overlayed"
  open: boolean
  setOpen: (open: boolean) => void
  openMobile: boolean
  setOpenMobile: (open: boolean) => void
  isMobile: boolean
  toggleSidebar: () => void
}

/**
 * React context carrying the sidebar open/collapsed state. Provided by
 * {@link SidebarProvider}; read via {@link useSidebar}.
 */
export const SidebarContext = React.createContext<SidebarContextProps | null>(null)

/**
 * Accesses the sidebar state and controls. Returns the
 * {@link SidebarContextProps} value: `state`, `open`/`setOpen`,
 * `openMobile`/`setOpenMobile`, `isMobile`, and `toggleSidebar`. Must be
 * called inside a {@link SidebarProvider}; throws otherwise.
 */
export function useSidebar() {
  const context = React.useContext(SidebarContext)
  if (!context) {
    throw new Error("useSidebar must be used within a SidebarProvider.")
  }

  return context
}

// ============================================================================
// PROVIDER
// ============================================================================

export function SidebarProvider({
    defaultOpen: defaultOpenProp,
    open: openProp,
    onOpenChange: setOpenProp,
    className,
    style,
    children,
    ...props
}: React.ComponentProps<'div'> & {
    defaultOpen?: boolean;
    open?: boolean;
    onOpenChange?: (open: boolean) => void;
}) {
    const isMobile = useIsMobile();

    const [openMobile, setOpenMobile] = React.useState(false);

    // Start with a consistent default for SSR (fallback: open on desktop).
    const [_open, _setOpen] = React.useState(defaultOpenProp ?? true);

    // Track if we've hydrated and read the cookie
    const [hasHydrated, setHasHydrated] = React.useState(false);

    // Read cookie AFTER hydration to avoid mismatch
    React.useEffect(() => {
        if (openProp !== undefined || defaultOpenProp !== undefined) {
            setHasHydrated(true);
            return;
        }

        const cookieValue = document.cookie
            .split('; ')
            .find((row) => row.startsWith(`${SIDEBAR_COOKIE_NAME}=`))
            ?.split('=')[1];

        if (cookieValue !== undefined) {
            _setOpen(cookieValue === 'true');
        }

        setHasHydrated(true);
    }, [openProp, defaultOpenProp]);

    // Viewport-based auto-adjust (only if no cookie preference).
    React.useEffect(() => {
        if (!hasHydrated) return;
        if (openProp !== undefined || defaultOpenProp !== undefined) return;

        const hasCookie = document.cookie.includes(SIDEBAR_COOKIE_NAME);

        if (!hasCookie && !isMobile) {
            _setOpen(true);
        }
    }, [hasHydrated, isMobile, openProp, defaultOpenProp]);

    const open = openProp ?? _open;

    const setOpen = React.useCallback(
        (value: boolean | ((value: boolean) => boolean)) => {
            const openState = typeof value === 'function' ? value(open) : value;
            if (setOpenProp) {
                setOpenProp(openState);
            } else {
                _setOpen(openState);
            }

            // This sets the cookie to keep the sidebar state.
            document.cookie = `${SIDEBAR_COOKIE_NAME}=${openState}; path=/; max-age=${SIDEBAR_COOKIE_MAX_AGE}`;
        },
        [setOpenProp, open],
    );

    // Helper to toggle the sidebar.
    const toggleSidebar = React.useCallback(() => {
        return isMobile ? setOpenMobile((open) => !open) : setOpen((open) => !open);
    }, [isMobile, setOpen, setOpenMobile]);

    // Adds a keyboard shortcut to toggle the sidebar.
    React.useEffect(() => {
        const handleKeyDown = (event: KeyboardEvent) => {
            if (event.key === SIDEBAR_KEYBOARD_SHORTCUT && (event.metaKey || event.ctrlKey)) {
                event.preventDefault();
                toggleSidebar();
            }
        };

        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [toggleSidebar]);

    // Desktop state reflects `open` only; on mobile the sidebar is presented
    // as an overlay sheet ('overlayed' when its mobile sheet is open). Keeping
    // these branches separate avoids the desktop state flipping when the mobile
    // sheet toggles.
    const state: SidebarContextProps['state'] = isMobile
        ? openMobile
            ? 'overlayed'
            : 'collapsed'
        : open
            ? 'expanded'
            : 'collapsed';

    const contextValue = React.useMemo<SidebarContextProps>(
        () => ({
            state,
            open,
            setOpen,
            isMobile: isMobile,
            openMobile,
            setOpenMobile,
            toggleSidebar,
        }),
        [state, open, setOpen, isMobile, openMobile, setOpenMobile, toggleSidebar],
    );

    return (
        <SidebarContext.Provider value={contextValue}>
            <TooltipProvider delayDuration={0}>
                <div
                    data-slot="sidebar-wrapper"
                    style={
                        {
                            '--sidebar-width': SIDEBAR_WIDTH,
                            '--sidebar-width-icon': SIDEBAR_WIDTH_ICON,
                            ...style,
                        } as React.CSSProperties
                    }
                    className={cn(
                        'group/sidebar-wrapper has-data-[variant=inset]:bg-sidebar flex h-svh w-full overflow-hidden',
                        className,
                    )}
                    {...props}
                >
                    {children}
                </div>
            </TooltipProvider>
        </SidebarContext.Provider>
    );
}

// ============================================================================
// TRIGGER
// ============================================================================

export function SidebarTrigger({
  className,
  onClick,
  surface,
  radius,
  animated,
  iconWeight,
  ...props
}: React.ComponentProps<typeof Button> & SaasflareComponentProps) {
  const { toggleSidebar } = useSidebar()
  const sf = useSaasflareProps({ surface, radius, animated, iconWeight })

  return (
    <Button
      data-sidebar="trigger"
      data-slot="sidebar-trigger"
      variant="ghost"
      size="icon"
      surface={sf.surface}
      radius={sf.radius}
      animated={sf.animated}
      iconWeight={sf.iconWeight}
      className={cn("size-7", className)}
      onClick={(event) => {
        onClick?.(event)
        toggleSidebar()
      }}
      {...props}
    >
      <SidebarSimpleIcon weight={sf.iconWeight} />
      <span className="sr-only">Toggle Sidebar</span>
    </Button>
  )
}
// @toreview
"use client"

/**
 * @fileoverview Sidebar layout components — main sidebar shell, rail, inset area, header, footer, content groups, and input.
 * Provides the structural layout primitives for the sidebar. Part of the Saasflare base component layer.
 * @module packages/ui/components/ui/sidebar/layout
 * @package ui
 *
 * @example
 * import { Sidebar, SidebarHeader, SidebarContent, SidebarGroup, SidebarFooter, SidebarInset } from '@saasflare/ui';
 * <Sidebar side="left" variant="sidebar" collapsible="offcanvas">
 *   <SidebarHeader>Logo</SidebarHeader>
 *   <SidebarContent>
 *     <SidebarGroup>Navigation items</SidebarGroup>
 *   </SidebarContent>
 *   <SidebarFooter>User menu</SidebarFooter>
 * </Sidebar>
 */

// ============================================================================
// SIDEBAR LAYOUT COMPONENTS
// Core layout components for the sidebar
// ============================================================================

// ============================================================================
// MAIN SIDEBAR
// ============================================================================

export interface SidebarProps extends Omit<React.ComponentProps<"div">, keyof SaasflareComponentProps>, SaasflareComponentProps {
  side?: "left" | "right"
  variant?: "sidebar" | "floating" | "inset"
  collapsible?: "offcanvas" | "icon" | "none"
}

/**
 * Root sidebar shell. Renders the collapsible navigation chrome and resolves the
 * design-system axes (`surface`, `radius`, `animated`) onto its root element across
 * the `collapsible="none"`, mobile (Sheet), and desktop branches.
 *
 * @example
 * <Sidebar side="left" variant="floating" collapsible="icon" surface="elevated" radius="lg">
 *   <SidebarHeader>Logo</SidebarHeader>
 *   <SidebarContent>
 *     <SidebarGroup>Navigation items</SidebarGroup>
 *   </SidebarContent>
 *   <SidebarFooter>User menu</SidebarFooter>
 * </Sidebar>
 */
export function Sidebar({
  side = "left",
  variant = "sidebar",
  collapsible = "offcanvas",
  className,
  children,
  surface,
  radius,
  animated,
  iconWeight,
  ...props
}: SidebarProps) {
  const { isMobile, state, openMobile, setOpenMobile } = useSidebar()
  const sf = useSaasflareProps({ surface, radius, animated, iconWeight })

  if (collapsible === "none") {
    return (
      <div
        {...props}
        data-slot="sidebar"
        data-surface={sf.surface}
        data-radius={sf.radius}
        data-animated={String(sf.animated)}
        className={cn(
          "bg-sidebar text-sidebar-foreground flex h-full w-(--sidebar-width) flex-col",
          className
        )}
      >
        {children}
      </div>
    )
  }

  if (isMobile) {
    return (
      <Sheet open={openMobile} onOpenChange={setOpenMobile} {...props}>
        <SheetContent
          data-sidebar="sidebar"
          data-slot="sidebar"
          data-mobile="true"
          surface={surface}
          radius={radius}
          animated={animated}
          className="bg-sidebar text-sidebar-foreground w-(--sidebar-width) p-0 [&>button]:hidden"
          style={
            {
              "--sidebar-width": SIDEBAR_WIDTH_MOBILE,
            } as React.CSSProperties
          }
          side={side}
        >
          <SheetHeader className="sr-only">
            <SheetTitle>Sidebar</SheetTitle>
            <SheetDescription>Displays the mobile sidebar.</SheetDescription>
          </SheetHeader>
          <div className="flex h-full w-full flex-col">{children}</div>
        </SheetContent>
      </Sheet>
    )
  }

  return (
    <div
      className="group peer text-sidebar-foreground hidden md:block"
      data-state={state}
      data-collapsible={state === "collapsed" ? collapsible : ""}
      data-variant={variant}
      data-side={side}
      data-slot="sidebar"
      data-surface={sf.surface}
      data-radius={sf.radius}
      data-animated={String(sf.animated)}
    >
      {/* This is what handles the sidebar gap on desktop */}
      <div
        data-slot="sidebar-gap"
        className={cn(
          "relative w-(--sidebar-width) bg-transparent transition-[width] duration-200 ease-linear",
          "group-data-[collapsible=offcanvas]:w-0",
          "group-data-[side=right]:rotate-180",
          variant === "floating" || variant === "inset"
            ? "group-data-[collapsible=icon]:w-[calc(var(--sidebar-width-icon)+(--spacing(4)))]"
            : "group-data-[collapsible=icon]:w-(--sidebar-width-icon)"
        )}
      />
      <div
        data-slot="sidebar-container"
        className={cn(
          "fixed inset-y-0 z-10 hidden h-svh w-(--sidebar-width) transition-[left,right,width] duration-200 ease-linear md:flex",
          side === "left"
            ? "left-0 group-data-[collapsible=offcanvas]:left-[calc(var(--sidebar-width)*-1)]"
            : "right-0 group-data-[collapsible=offcanvas]:right-[calc(var(--sidebar-width)*-1)]",
          // Adjust the padding for floating and inset variants.
          variant === "floating" || variant === "inset"
            ? "p-2 group-data-[collapsible=icon]:w-[calc(var(--sidebar-width-icon)+(--spacing(4))+2px)]"
            : "group-data-[collapsible=icon]:w-(--sidebar-width-icon) group-data-[side=left]:border-r group-data-[side=right]:border-l",
          className
        )}
        {...props}
      >
        <div
          data-sidebar="sidebar"
          data-slot="sidebar-inner"
          className="bg-sidebar group-data-[variant=floating]:border-sidebar-border flex h-full w-full flex-col group-data-[variant=floating]:rounded-lg group-data-[variant=floating]:border group-data-[variant=floating]:shadow-sm"
        >
          {children}
        </div>
      </div>
    </div>
  )
}

// ============================================================================
// SIDEBAR SECTIONS
// ============================================================================

/**
 * Interactive rail along the sidebar edge that toggles the collapsed/expanded state.
 *
 * @example
 * <Sidebar collapsible="icon">…<SidebarRail /></Sidebar>
 */
export function SidebarRail({ className, ...props }: React.ComponentProps<"button">) {
  const { toggleSidebar } = useSidebar()

  return (
    <button
      data-sidebar="rail"
      data-slot="sidebar-rail"
      aria-label="Toggle Sidebar"
      tabIndex={-1}
      onClick={toggleSidebar}
      title="Toggle Sidebar"
      className={cn(
        "hover:after:bg-sidebar-border absolute inset-y-0 z-20 hidden w-4 -translate-x-1/2 transition-all ease-linear group-data-[side=left]:-right-4 group-data-[side=right]:left-0 after:absolute after:inset-y-0 after:left-1/2 after:w-[2px] sm:flex",
        "in-data-[side=left]:cursor-w-resize in-data-[side=right]:cursor-e-resize",
        "[[data-side=left][data-state=collapsed]_&]:cursor-e-resize [[data-side=right][data-state=collapsed]_&]:cursor-w-resize",
        "hover:group-data-[collapsible=offcanvas]:bg-sidebar group-data-[collapsible=offcanvas]:translate-x-0 group-data-[collapsible=offcanvas]:after:left-full",
        "[[data-side=left][data-collapsible=offcanvas]_&]:-right-2",
        "[[data-side=right][data-collapsible=offcanvas]_&]:-left-2",
        className
      )}
      {...props}
    />
  )
}

/**
 * Props for {@link SidebarInset}. Extends `<main>` props with
 * {@link SaasflareComponentProps} (`surface`, `radius`, `animated`, `iconWeight`).
 */
export interface SidebarInsetProps
  extends Omit<React.ComponentProps<"main">, keyof SaasflareComponentProps>,
    SaasflareComponentProps {}

/**
 * Main content area that sits beside the sidebar. For the `inset` variant it gains a
 * rounded, elevated surface offset from the sidebar, so it carries the
 * `surface`/`radius`/`animated` axes.
 *
 * @example
 * <SidebarInset surface="elevated" radius="xl">
 *   <PageContent />
 * </SidebarInset>
 */
export function SidebarInset({
  className,
  surface,
  radius,
  animated,
  iconWeight,
  ...props
}: SidebarInsetProps) {
  const sf = useSaasflareProps({ surface, radius, animated, iconWeight })

  return (
    <main
      data-slot="sidebar-inset"
      data-surface={sf.surface}
      data-radius={sf.radius}
      data-animated={String(sf.animated)}
      className={cn(
        "bg-background relative flex w-full flex-1 flex-col overflow-auto",
        "md:peer-data-[variant=inset]:m-2 md:peer-data-[variant=inset]:ml-0 md:peer-data-[variant=inset]:rounded-xl md:peer-data-[variant=inset]:shadow-sm md:peer-data-[variant=inset]:peer-data-[state=collapsed]:ml-2",
        className
      )}
      {...props}
    />
  )
}

/**
 * Search/filter input styled for placement inside the sidebar header.
 *
 * @example
 * <SidebarHeader><SidebarInput placeholder="Search…" /></SidebarHeader>
 */
export function SidebarInput({
  className,
  ...props
}: React.ComponentProps<typeof Input>) {
  return (
    <Input
      data-slot="sidebar-input"
      data-sidebar="input"
      className={cn("bg-background h-8 w-full shadow-none", className)}
      {...props}
    />
  )
}

/**
 * Top region of the sidebar, typically holding the brand/logo or a search input.
 *
 * @example
 * <SidebarHeader>Logo</SidebarHeader>
 */
export function SidebarHeader({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="sidebar-header"
      data-sidebar="header"
      className={cn("flex flex-col gap-2 p-2", className)}
      {...props}
    />
  )
}

/**
 * Bottom region of the sidebar, typically holding the user menu or secondary actions.
 *
 * @example
 * <SidebarFooter>User menu</SidebarFooter>
 */
export function SidebarFooter({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="sidebar-footer"
      data-sidebar="footer"
      className={cn("flex flex-col gap-2 p-2", className)}
      {...props}
    />
  )
}

/**
 * Props for {@link SidebarSeparator}. Extends {@link Separator} props with
 * {@link SaasflareComponentProps} (`surface`, `radius`, `animated`, `iconWeight`).
 */
export interface SidebarSeparatorProps
  extends Omit<React.ComponentProps<typeof Separator>, keyof SaasflareComponentProps>,
    SaasflareComponentProps {}

/**
 * Horizontal divider styled for use between sidebar sections. Carries the
 * `surface`/`radius`/`animated` axes onto its rendered border element.
 *
 * @example
 * <SidebarGroup>…</SidebarGroup>
 * <SidebarSeparator />
 * <SidebarGroup>…</SidebarGroup>
 */
export function SidebarSeparator({
  className,
  surface,
  radius,
  animated,
  iconWeight,
  ...props
}: SidebarSeparatorProps) {
  const sf = useSaasflareProps({ surface, radius, animated, iconWeight })

  return (
    <Separator
      data-slot="sidebar-separator"
      data-sidebar="separator"
      data-surface={sf.surface}
      data-radius={sf.radius}
      data-animated={String(sf.animated)}
      className={cn("bg-sidebar-border mx-2 w-auto", className)}
      {...props}
    />
  )
}

/**
 * Scrollable middle region of the sidebar that holds the navigation groups.
 *
 * @example
 * <SidebarContent><SidebarGroup>…</SidebarGroup></SidebarContent>
 */
export function SidebarContent({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="sidebar-content"
      data-sidebar="content"
      className={cn(
        "flex min-h-0 flex-1 flex-col gap-2 overflow-auto group-data-[collapsible=icon]:overflow-hidden",
        className
      )}
      {...props}
    />
  )
}

/**
 * Logical grouping of sidebar items, optionally labelled and with a group action.
 *
 * @example
 * <SidebarGroup>
 *   <SidebarGroupLabel>Projects</SidebarGroupLabel>
 *   <SidebarGroupContent>…</SidebarGroupContent>
 * </SidebarGroup>
 */
export function SidebarGroup({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="sidebar-group"
      data-sidebar="group"
      className={cn("relative flex w-full min-w-0 flex-col p-2", className)}
      {...props}
    />
  )
}

/**
 * Heading for a sidebar group. Pass `asChild` to render as a custom element.
 *
 * @example
 * <SidebarGroupLabel>Projects</SidebarGroupLabel>
 */
export function SidebarGroupLabel({
  className,
  asChild = false,
  ...props
}: React.ComponentProps<"div"> & { asChild?: boolean }) {
  const Comp = asChild ? Slot.Root : "div"

  return (
    <Comp
      data-slot="sidebar-group-label"
      data-sidebar="group-label"
      className={cn(
        "text-sidebar-foreground/70 ring-sidebar-ring flex h-8 shrink-0 items-center rounded-md px-2 text-xs font-medium outline-hidden transition-[margin,opacity] duration-200 ease-linear focus-visible:ring-2 [&>svg]:size-4 [&>svg]:shrink-0",
        "group-data-[collapsible=icon]:-mt-8 group-data-[collapsible=icon]:opacity-0",
        className
      )}
      {...props}
    />
  )
}

/**
 * Action button anchored to the top-right of a sidebar group. Pass `asChild` to
 * render as a custom element.
 *
 * @example
 * <SidebarGroup>
 *   <SidebarGroupLabel>Projects</SidebarGroupLabel>
 *   <SidebarGroupAction title="Add project"><PlusIcon /></SidebarGroupAction>
 * </SidebarGroup>
 */
export function SidebarGroupAction({
  className,
  asChild = false,
  ...props
}: React.ComponentProps<"button"> & { asChild?: boolean }) {
  const Comp = asChild ? Slot.Root : "button"

  return (
    <Comp
      data-slot="sidebar-group-action"
      data-sidebar="group-action"
      className={cn(
        "text-sidebar-foreground ring-sidebar-ring hover:bg-sidebar-accent hover:text-sidebar-accent-foreground absolute top-3.5 right-3 flex aspect-square w-5 items-center justify-center rounded-md p-0 outline-hidden transition-transform focus-visible:ring-2 [&>svg]:size-4 [&>svg]:shrink-0",
        // Increases the hit area of the button on mobile.
        "after:absolute after:-inset-2 md:after:hidden",
        "group-data-[collapsible=icon]:hidden",
        className
      )}
      {...props}
    />
  )
}

/**
 * Container for the items inside a sidebar group (typically a `SidebarMenu`).
 *
 * @example
 * <SidebarGroupContent><SidebarMenu>…</SidebarMenu></SidebarGroupContent>
 */
export function SidebarGroupContent({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="sidebar-group-content"
      data-sidebar="group-content"
      className={cn("w-full text-sm", className)}
      {...props}
    />
  )
}
// @toreview
"use client"

/**
 * @fileoverview Sidebar menu components — menu items, buttons with tooltip support, sub-menus, actions, badges, and skeletons.
 * Provides the interactive menu primitives for the sidebar. Part of the Saasflare base component layer.
 * @module packages/ui/components/ui/sidebar/menu
 * @package ui
 *
 * @example
 * import { SidebarMenu, SidebarMenuItem, SidebarMenuButton } from '@saasflare/ui';
 * <SidebarMenu>
 *   <SidebarMenuItem>
 *     <SidebarMenuButton tooltip="Dashboard" isActive>
 *       Dashboard
 *     </SidebarMenuButton>
 *   </SidebarMenuItem>
 * </SidebarMenu>
 */

// ============================================================================
// SIDEBAR MENU COMPONENTS
// Menu-related components for the sidebar
// ============================================================================

// ============================================================================
// MENU BUTTON VARIANTS
// ============================================================================

export const sidebarMenuButtonVariants = cva(
  "peer/menu-button relative flex w-full items-center gap-2 overflow-hidden rounded-md p-2 text-left text-sm outline-hidden ring-sidebar-ring transition-[width,height,padding,background-color,color] hover:bg-sidebar-accent hover:text-sidebar-accent-foreground focus-visible:ring-2 active:bg-sidebar-accent active:text-sidebar-accent-foreground disabled:pointer-events-none disabled:opacity-50 group-has-data-[sidebar=menu-action]/menu-item:pr-8 aria-disabled:pointer-events-none aria-disabled:opacity-50 data-[active=true]:bg-[color-mix(in_oklch,var(--sidebar-primary)_10%,transparent)] data-[active=true]:font-semibold data-[active=true]:text-sidebar-primary data-[active=true]:before:absolute data-[active=true]:before:left-0 data-[active=true]:before:top-1/2 data-[active=true]:before:h-[60%] data-[active=true]:before:w-[3px] data-[active=true]:before:-translate-y-1/2 data-[active=true]:before:rounded-r data-[active=true]:before:bg-sidebar-primary data-[active=true]:before:content-[''] data-[state=open]:hover:bg-sidebar-accent data-[state=open]:hover:text-sidebar-accent-foreground group-data-[collapsible=icon]:size-8! group-data-[collapsible=icon]:p-2! [&>span:last-child]:truncate [&>svg]:size-4 [&>svg]:shrink-0",
  {
    variants: {
      variant: {
        default: "hover:bg-sidebar-accent hover:text-sidebar-accent-foreground",
        outline:
          "bg-background shadow-[0_0_0_1px_var(--sidebar-border)] hover:bg-sidebar-accent hover:text-sidebar-accent-foreground hover:shadow-[0_0_0_1px_var(--sidebar-accent)]",
      },
      size: {
        md: "h-8 text-sm",
        sm: "h-7 text-xs",
        lg: "h-12 text-sm group-data-[collapsible=icon]:p-0!",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "md",
    },
  }
)

// ============================================================================
// MENU COMPONENTS
// ============================================================================

/**
 * Top-level menu list container for the sidebar. Renders a `<ul>` that lays out
 * {@link SidebarMenuItem} children in a vertical stack.
 */
export function SidebarMenu({ className, ...props }: React.ComponentProps<"ul">) {
  return (
    <ul
      data-slot="sidebar-menu"
      data-sidebar="menu"
      className={cn("flex w-full min-w-0 flex-col gap-1", className)}
      {...props}
    />
  )
}

/**
 * Wrapper for a single menu entry. Renders a `<li>` and establishes the
 * `group/menu-item` scope used by actions, badges, and active-state styling.
 */
export function SidebarMenuItem({ className, ...props }: React.ComponentProps<"li">) {
  return (
    <li
      data-slot="sidebar-menu-item"
      data-sidebar="menu-item"
      className={cn("group/menu-item relative", className)}
      {...props}
    />
  )
}

/** Props for {@link SidebarMenuButton}. */
export interface SidebarMenuButtonProps
  extends Omit<React.ComponentProps<"button">, keyof SaasflareComponentProps>,
    SaasflareComponentProps,
    Omit<VariantProps<typeof sidebarMenuButtonVariants>, "size"> {
  /** Visual size. (`"default"` is a deprecated alias for `"md"`.) */
  size?: VariantProps<typeof sidebarMenuButtonVariants>["size"] | "default"
  /** Render via Radix `Slot` instead of a `<button>`, merging props onto the child. */
  asChild?: boolean
  /** Marks the button as the active route. Drives the accent indicator + emphasis. */
  isActive?: boolean
  /** Tooltip shown when the sidebar is collapsed. Pass a string or `TooltipContent` props. */
  tooltip?: string | React.ComponentProps<typeof TooltipContent>
}

/**
 * Primary interactive menu button. Supports active state, size/variant styling,
 * and an optional tooltip that surfaces the label when the sidebar is collapsed.
 */
export function SidebarMenuButton({
  asChild = false,
  isActive = false,
  variant = "default",
  size = "md",
  tooltip,
  className,
  surface,
  radius,
  animated,
  iconWeight,
  ...props
}: SidebarMenuButtonProps) {
  const Comp = asChild ? Slot.Root : "button"
  const { isMobile, state } = useSidebar()
  const sf = useSaasflareProps({ surface, radius, animated, iconWeight })
  const resolvedSize = size === "default" ? "md" : size

  const button = (
    <Comp
      data-slot="sidebar-menu-button"
      data-sidebar="menu-button"
      data-size={resolvedSize}
      data-active={isActive}
      data-surface={sf.surface}
      data-radius={sf.radius}
      data-animated={String(sf.animated)}
      className={cn(sidebarMenuButtonVariants({ variant, size: resolvedSize }), className)}
      {...props}
    />
  )

  if (!tooltip) {
    return button
  }

  const tooltipProps: React.ComponentProps<typeof TooltipContent> =
    typeof tooltip === "string" ? { children: tooltip } : tooltip

  return (
    <Tooltip>
      <TooltipTrigger asChild>{button}</TooltipTrigger>
      <TooltipContent
        side="right"
        align="center"
        hidden={state !== "collapsed" || isMobile}
        {...tooltipProps}
      />
    </Tooltip>
  )
}

